class Solution {
    long long MOD = 1000000007;

    long long modPow(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }

public:
    std::vector<int> assignEdgeWeights(std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& queries) {
        int num_nodes = edges.size() + 1;
        std::vector<std::vector<int>> graph(num_nodes + 1);
        for (const auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
        }

        const int kLog = 20;
        std::vector<std::vector<int>> parent(kLog, std::vector<int>(num_nodes + 1, 0));
        std::vector<int> depth(num_nodes + 1, 0);

        auto dfs = [&](auto& self, int u, int p, int d) -> void {
            depth[u] = d;
            parent[0][u] = p;
            for (int v : graph[u]) {
                if (v != p) {
                    self(self, v, u, d + 1);
                }
            }
        };
        dfs(dfs, 1, 0, 0);

        for (int k = 1; k < kLog; ++k) {
            for (int i = 1; i <= num_nodes; ++i) {
                parent[k][i] = parent[k - 1][parent[k - 1][i]];
            }
        }

        auto lca = [&](int u, int v) -> int {
            if (depth[u] < depth[v]) std::swap(u, v);
            for (int k = kLog - 1; k >= 0; --k) {
                if (depth[u] - (1 << k) >= depth[v]) {
                    u = parent[k][u];
                }
            }
            if (u == v) return u;
            for (int k = kLog - 1; k >= 0; --k) {
                if (parent[k][u] != parent[k][v]) {
                    u = parent[k][u];
                    v = parent[k][v];
                }
            }
            return parent[0][u];
        };

        std::vector<int> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            int u = q[0], v = q[1];
            if (u == v) {
                ans.push_back(0);
            } else {
                int anc = lca(u, v);
                int d = depth[u] + depth[v] - 2 * depth[anc];
                ans.push_back(modPow(2, d - 1));
            }
        }
        return ans;
    }
