import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2;
        }
        return res;
    }

    public int[] assignEdgeWeights(int[][] edges, int[][] queries) {
        int numNodes = edges.length + 1;
        List<Integer>[] graph = new ArrayList[numNodes + 1];
        for (int i = 0; i <= numNodes; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        int kLog = 20;
        int[][] parent = new int[kLog][numNodes + 1];
        int[] depth = new int[numNodes + 1];

        dfs(1, 0, 0, graph, parent, depth);

        for (int k = 1; k < kLog; ++k) {
            for (int i = 1; i <= numNodes; ++i) {
                parent[k][i] = parent[k - 1][parent[k - 1][i]];
            }
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int u = queries[i][0], v = queries[i][1];
            if (u == v) {
                ans[i] = 0;
            } else {
                int anc = lca(u, v, parent, depth, kLog);
                int d = depth[u] + depth[v] - 2 * depth[anc];
                ans[i] = (int) modPow(2, d - 1);
            }
        }
        return ans;
    }

    private void dfs(int u, int p, int d, List<Integer>[] graph, int[][] parent, int[] depth) {
        depth[u] = d;
        parent[0][u] = p;
        for (int v : graph[u]) {
            if (v != p) {
                dfs(v, u, d + 1, graph, parent, depth);
            }
        }
    }

    private int lca(int u, int v, int[][] parent, int[] depth, int kLog) {
        if (depth[u] < depth[v]) {
            int t = u; u = v; v = t;
        }
        for (int k = kLog - 1; k >= 0; --k) {
            if (depth[u] - (1 << k) >= depth[v]) {
                u = parent[k][u];
            }
        }
        if (u == v) return u;
        for (int k = kLog - 1; k >= 0; --k) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }
}

/**
 * @param {number[][]} edges
 * @param {number[][]} queries
 * @return {number[]}
 */
var assignEdgeWeights = function(edges, queries) {
    const MOD = 1000000007n;
    const numNodes = edges.length + 1;

    const graph = Array.from({ length: numNodes + 1 }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const kLog = 20;
    const parent = Array.from({ length: kLog }, () => new Array(numNodes + 1).fill(0));
    const depth = new Array(numNodes + 1).fill(0);

    function dfs(u, p, d) {
        depth[u] = d;
        parent[0][u] = p;
        for (const v of graph[u]) {
            if (v !== p) {
                dfs(v, u, d + 1);
            }
        }
    }

    dfs(1, 0, 0);

    for (let k = 1; k < kLog; ++k) {
        for (let i = 1; i <= numNodes; ++i) {
            parent[k][i] = parent[k - 1][parent[k - 1][i]];
        }
    }

    function lca(u, v) {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        for (let k = kLog - 1; k >= 0; --k) {
            if (depth[u] - (1 << k) >= depth[v]) {
                u = parent[k][u];
            }
        }
        if (u === v) return u;
        for (let k = kLog - 1; k >= 0; --k) {
            if (parent[k][u] !== parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }

    function modPow(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    }

    const ans = [];
    for (const [u, v] of queries) {
        if (u === v) {
            ans.push(0);
        } else {
            const anc = lca(u, v);
            const d = depth[u] + depth[v] - 2 * depth[anc];
            ans.push(Number(modPow(2n, BigInt(d - 1))));
        }
    }
    return ans;
};
